--
-- Table structure for table `questions`
--

DROP TABLE IF EXISTS `questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subject_id` bigint unsigned NOT NULL,
  `topic_id` bigint unsigned NOT NULL,
  `stimulus_id` bigint unsigned DEFAULT NULL,
  `order_in_group` tinyint unsigned NOT NULL DEFAULT '1',
  `statement` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `difficulty` enum('easy','medium','hard') COLLATE utf8mb4_unicode_ci NOT NULL,
  `explanation` text COLLATE utf8mb4_unicode_ci,
  `source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_pdf` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_page` smallint unsigned DEFAULT NULL,
  `original_question_number` smallint unsigned DEFAULT NULL,
  `status` enum('draft','review','published','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `questions_subject_id_index` (`subject_id`),
  KEY `questions_topic_id_index` (`topic_id`),
  KEY `questions_stimulus_id_index` (`stimulus_id`),
  KEY `questions_status_index` (`status`),
  CONSTRAINT `questions_stimulus_id_foreign` FOREIGN KEY (`stimulus_id`) REFERENCES `stimuli` (`id`) ON DELETE SET NULL,
  CONSTRAINT `questions_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `questions_topic_id_foreign` FOREIGN KEY (`topic_id`) REFERENCES `topics` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

