INSERT INTO `stimuli` VALUES (1,1,'Distribución de Horas de Estudio y Rendimiento Académico (Datos de Prueba ATHENA)','Responda las preguntas asociadas con base en la información del estudio muestral.','En un estudio piloto con 100 estudiantes que preparan la prueba de Estado, se analizaron las horas semanales de estudio independiente y el puntaje obtenido en los simulacros diagnósticos:\n- El 30% de los estudiantes dedicó menos de 5 horas semanales, obteniendo un puntaje medio de 52 puntos.\n- El 50% de los estudiantes dedicó entre 5 y 10 horas semanales, obteniendo un puntaje medio de 71 puntos.\n- El 20% de los estudiantes dedicó más de 10 horas semanales, obteniendo un puntaje medio de 89 puntos.','none',NULL,NULL,NULL,NULL,NULL,'2026-10-22 18:28:28','2026-10-22 18:28:28',NULL);
